(function(root){
 'use strict';
 const $=selector=>document.querySelector(selector);let request=0,busy=false,state={state:'checking',owner:null};const subscribers=new Set();
 function publish(next){state=next;for(const listener of subscribers){try{listener({...state});}catch{}}}
 root.KashierAccount={subscribe(listener){if(typeof listener!=='function')throw Error('Invalid account subscriber');subscribers.add(listener);listener({...state});return ()=>subscribers.delete(listener);}};
 function showGuest(message){publish({state:'guest',owner:null});$('#account-summary').textContent='نەچوویتە ژوورەوە';$('#account-status').textContent=message||'بە هەژماری کاشێر بچۆ ژوورەوە';$('#account-email').textContent='';$('#account-login').hidden=false;$('#account-create').hidden=false;$('#account-logout').hidden=true;$('#account-retry').hidden=true;$('#account-help').textContent='هەژماری کاشێر لە هەژماری ChatGPT جیاوازە. پاش چوونەژوورەوە، بەشە چالاکەکان لە هەمان تابدا بەکاردێن.';}
 async function load(){const current=++request;if(!KashierData.loggedIn()){showGuest();return;}publish({state:'checking',owner:null});$('#account-summary').textContent='پشکنینی هەژمار…';$('#account-status').textContent='پشتڕاستکردنەوەی چوونەژوورەوە…';$('#account-login').hidden=true;$('#account-create').hidden=true;$('#account-logout').hidden=false;$('#account-retry').hidden=true;try{const account=await KashierData.getAccount();if(current!==request)return;$('#account-summary').textContent='چوویتە ژوورەوە';$('#account-status').textContent='هەژمارەکەت چالاکە';$('#account-email').textContent=account.email;$('#account-help').textContent='داتای هەژمارەکەت تایبەتە بە خۆت. بۆ دەستپێکردن، کاڵا بناسێنە، کڕین تۆمار بکە و پاشان فرۆشتن بکە.';publish({state:'ready',owner:account.id});}catch(error){if(current!==request)return;if(!KashierData.loggedIn()){showGuest('پێویستە دووبارە بچیتە ژوورەوە.');return;}publish({state:'error',owner:null});$('#account-summary').textContent='دۆخی هەژمار پشتڕاست نەکراوە';$('#account-status').textContent=error.message;$('#account-email').textContent='';$('#account-help').textContent='پەیوەندییەکەت بپشکنە و دووبارە پشکنینەوە بکە. لەم دۆخەدا هەژمارەکەت نەسڕاوەتەوە.';$('#account-retry').hidden=false;}}
 $('#account-retry').addEventListener('click',load);
 $('#account-logout').addEventListener('click',async()=>{if(busy)return;busy=true;request++;publish({state:'checking',owner:null});$('#account-logout').disabled=true;$('#account-retry').hidden=true;try{await KashierData.signOut();showGuest('لە هەژمارەکەت دەرچوویت.');}catch{showGuest('لەم تابە دەرچوویت؛ پەیوەندی بە سێرڤەر تەواو نەبوو.');}finally{busy=false;$('#account-logout').disabled=false;}});
 window.addEventListener('pageshow',event=>{if(event.persisted&&!busy)load();});
 load();
})(globalThis);
